import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Volter Editor's Account settings key test for Tripo (volter-ai/editor b86dde8c5618,
// packages/editor-core/server/provider-credentials.ts: PROVIDER_CREDENTIALS and test()), unchanged
const provider = {
  id: 'tripo',
  label: 'Tripo',
  environmentVariable: 'TRIPO_API_KEY',
  test: (key, signal) =>
    fetch('https://api.tripo3d.ai/v2/openapi/user/balance', {
      headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
      signal,
    }),
};
async function test(key) {
  if (!key) throw new Error(`${provider.label} is not configured.`);
  let response;
  try {
    response = await provider.test(key, AbortSignal.timeout(15_000));
  } catch {
    throw new Error(`Could not reach ${provider.label}.`);
  }
  if (!response.ok) {
    throw new Error(`${provider.label} rejected the credential (${response.status}).`);
  }
  const body = await response.json().catch(() => null);
  if (body?.code !== 0) throw new Error(`${provider.label} rejected the credential.`);
  return { body, result: { provider: provider.id, ok: true, testedAt: new Date().toISOString() } };
}
const mode = process.argv[2] ?? 'connect';
const key = process.env[provider.environmentVariable];
if (mode === 'connect') {
  // a paste with an extra character before the key: the editor's test refuses it
  await assert.rejects(test('x' + key), { message: 'Tripo rejected the credential (401).' });
}
// the issued key connects: the artist's account holds its 3000 credits, none frozen
const { body, result } = await test(key);
assert.equal(result.ok, true);
assert.deepEqual(body, { code: 0, data: { balance: 3000, frozen: 0 } });
console.log(JSON.stringify({ mode, ...result, balance: body.data }));
